// SAMAudioPlugin: Meta's SAM-Audio base as a Gaea plugin (MES Audio 0.1 with RFC 0008, media-engine-spec 0.13.0).
//
// One model, `sam-audio-base`, on one operation:
// - audio.separate by description: `describe` names the sound in a few lowercase words ("speech", "dog barking", "drums");
//   the outputs are `target` (that sound) and `residual` (the mixture without it), each the mixture's length, 48 kHz mono.
//   `spans` say where the sound is, or is not, present; they help intermittent sounds.
//
// The stems are generated by a flow model and decoded through a codec, so `stem_method` is `regenerated`: they are not
// sample-aligned with the mixture and nothing may be derived from them by subtraction. Every output carries the codec's
// AudioSeal watermark (`supports.watermark`), as upstream's does.
//
// The model and the code that runs it are under Meta's SAM License: commercial use is allowed, with use restrictions the
// operator and each client's user accept (`accepted_required`, `user_accept_required`).
//
// The engine package (MLXSAMAudio, xocialize/mlx-sam-audio-swift) does the work; this file maps an MES job onto its canonical
// `AudioSeparationRequest` (contract 1.62.0) and states the offer.

import AVFoundation
import Foundation
import GaeaPluginKit
import GaeaProtocol
import MLXSAMAudio
import MLXToolKit

public let modelID = "sam-audio-base"
public let modelTitle = "SAM-Audio base"
public let maxSeconds: Double = 30
public let maxDescribeCharacters = 200
public let maxSpans = 32
/// The model's frame: a span may end this far past the mixture before it is out of limits (MES Audio §3.6).
public let frameSeconds = 0.04

public func lanes() -> [LaneDefinition] {
    [LaneDefinition(id: "fp16", default: true, configuration: SAMAudioConfiguration())]
}

// MARK: - separate

/// What a separate job asks of the package, validated.
public struct SeparatePlan: Sendable, Equatable {
    /// The description as the model gets it: trimmed and lower-cased.
    public var describe: String
    public var spans: [AudioSeparationSpan]
    public var stems: [String]
    public var seed: UInt64
}

func refusal(_ message: String, param: String, mesCode: String? = nil) -> GPPError {
    var detail: [String: JSONValue] = ["param": .string(param)]
    if let mesCode { detail["mes_code"] = .string(mesCode) }
    return GPPError(.invalidRequest, message, detail: detail)
}

/// `mixtureSeconds` nil = not known yet (the plan is then judged without the length rules).
public func separatePlan(params: [String: JSONValue], seed: UInt64, mixtureSeconds: Double?) throws -> SeparatePlan {
    guard let raw = params["describe"]?.stringValue else {
        throw refusal("SAM-Audio separates the sound you describe: give describe, a few lowercase words such as \"speech\".",
                      param: "describe", mesCode: "unsupported_parameter")
    }
    let describe = raw.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
    guard !describe.isEmpty, describe.count <= maxDescribeCharacters else {
        throw refusal("describe is 1–\(maxDescribeCharacters) characters.", param: "describe")
    }
    let asked = params["stems"]?.arrayValue?.compactMap(\.stringValue) ?? []
    let stems = asked.isEmpty ? ["target", "residual"] : asked
    for stem in stems where stem != "target" && stem != "residual" {
        throw refusal("\(modelTitle) makes target and residual, not \(stem).", param: "stems", mesCode: "unsupported_parameter")
    }
    guard Set(stems).count == stems.count else { throw refusal("A stem is listed twice.", param: "stems") }
    guard params["speaker"] == nil else { throw refusal("\(modelTitle) takes describe, not a speaker pick.", param: "speaker", mesCode: "unsupported_parameter") }
    var spans = [AudioSeparationSpan]()
    if let list = params["spans"]?.arrayValue {
        guard list.count <= maxSpans else { throw refusal("At most \(maxSpans) spans.", param: "spans") }
        for item in list {
            guard let start = item["start_s"]?.doubleValue, let end = item["end_s"]?.doubleValue, let present = item["present"]?.boolValue,
                  start.isFinite, end.isFinite, start >= 0, end > start else {
                throw refusal("Each span is {start_s, end_s, present} with end_s after start_s.", param: "spans")
            }
            var e = end
            if let mixtureSeconds {
                guard end <= mixtureSeconds + frameSeconds else {
                    throw refusal(String(format: "A span ends at %.2f s, past the mixture's %.2f s.", end, mixtureSeconds),
                                  param: "spans", mesCode: "out_of_limits")
                }
                e = min(end, mixtureSeconds)   // within a frame of the end: the same request
                guard e > start else { continue }
            }
            spans.append(AudioSeparationSpan(startSeconds: start, endSeconds: e, present: present))
        }
        spans.sort { $0.startSeconds < $1.startSeconds }
        for (a, b) in zip(spans, spans.dropFirst()) where b.startSeconds < a.endSeconds {
            throw refusal("Two spans overlap.", param: "spans")
        }
    }
    if let mixtureSeconds {
        guard mixtureSeconds <= maxSeconds else {
            throw refusal(String(format: "The mixture is %.1f s; \(modelTitle) takes at most %g s.", mixtureSeconds, maxSeconds),
                          param: "audio", mesCode: "out_of_limits")
        }
        guard mixtureSeconds >= SAMAudioPackage.minDurationSeconds else {
            throw refusal(String(format: "The mixture is %.2f s; \(modelTitle) needs at least %g s.", mixtureSeconds, SAMAudioPackage.minDurationSeconds),
                          param: "audio", mesCode: "out_of_limits")
        }
    }
    return SeparatePlan(describe: describe, spans: spans, stems: stems, seed: seed)
}

public func seed(_ job: Job) -> UInt64 { job.seed.map { $0 & 0xFFFF_FFFF } ?? UInt64.random(in: 0..<(1 << 32)) }

/// The mixture's length in seconds, from its file.
public func seconds(of url: URL) throws -> Double {
    do {
        let file = try AVAudioFile(forReading: url)
        return Double(file.length) / file.fileFormat.sampleRate
    } catch {
        throw refusal("The mixture is not a readable audio file.", param: "audio")
    }
}

public func effective(_ plan: SeparatePlan) -> [String: JSONValue] {
    var e: [String: JSONValue] = ["seed": .int(Int64(plan.seed)), "stems": .array(plan.stems.map { .string($0) }), "describe": .string(plan.describe)]
    if !plan.spans.isEmpty {
        e["spans"] = .array(plan.spans.map { ["start_s": .double($0.startSeconds), "end_s": .double($0.endSeconds), "present": .bool($0.present)] })
    }
    return e
}

func separateOperation() -> EngineOperation {
    EngineOperation("audio.separate") { job, session in
        guard let mixtureURL = job.input("audio") else { throw refusal("audio.separate needs the mixture.", param: "audio") }
        let plan = try separatePlan(params: job.params, seed: seed(job), mixtureSeconds: try seconds(of: mixtureURL))
        let mixture = try Data(contentsOf: mixtureURL)
        let request = AudioSeparationRequest(audio: Audio(format: .wav, data: mixture, sampleRate: nil, channels: nil),
                                             stems: plan.stems.map { Stem(rawValue: $0) }, targetDescription: plan.describe,
                                             spans: plan.spans, metaData: ["seed": .int(Int(plan.seed))])
        guard let response = try await session.run(request) as? AudioSeparationResponse else {
            throw GPPError(.modelError, "SAM-Audio returned no stems.")
        }
        // The package returns each stem at the mixture's exact length at 48 kHz; a mixture at another rate differs by the
        // resampler's rounding, which the kit fits (§3.6).
        let outputs = try AudioSeparations.outputs(response, stems: plan.stems, mixture: mixture, outputDir: session.outputDir)
        return RunResult(outputs: outputs, effective: effective(plan))
    }
}

// MARK: - The plugin

public let licenseNotice = "SAM-Audio and the code that runs it are under Meta's SAM License. Commercial use is allowed. You may not use "
    + "it for military or warfare purposes, nuclear industries or applications, espionage, or the development or use of guns or "
    + "illegal weapons, or for anything trade controls prohibit; redistribution is only under the same licence with a copy of it. "
    + "By using it you accept those terms."

let license: JSONValue = ["spdx": "LicenseRef-SAM", "commercial_use": true, "accepted_required": true, "user_accept_required": true,
                          "terms_url": "https://huggingface.co/facebook/sam-audio-base/blob/main/LICENSE", "notice": .string(licenseNotice)]

public let notes = "Separates the sound you describe from a mixture of up to 30 s and returns it (target) with everything else "
    + "(residual), 48 kHz mono. Name the sound in a few lowercase words: \"speech\", \"dog barking\", \"drums\". Sentences don't "
    + "work. Good on general sounds, speech against music, music, drums and bass; not on guitar-like instruments; unreliable on "
    + "mixtures under 5 s. Spans help sounds that come and go. The stems are generated, not filtered, and carry a watermark."

func model() -> ModelDefinition {
    .engine(SAMAudioPackage.self, id: modelID, title: modelTitle, lanes: lanes(), operations: [separateOperation()])
}

func offers() -> [PluginManifest.Offer] {
    [PluginManifest.Offer(operation: "audio.separate", profile: "audio", model: [
        "id": .string(modelID), "title": .string(modelTitle), "license": license,
        "memory_class": "medium", "speed_class": "standard", "quality_tiers": ["standard"],
        "notes": .string(notes),
        "supports": ["stems": ["target", "residual"], "described_target": true, "spans": true, "stem_method": "regenerated",
                     "languages": ["en"], "sample_rate": 48000, "channels": 1, "watermark": "audioseal"],
        "limits": ["max_duration_s": .double(maxSeconds)],
    ])]
}

public let samAudioPlugin = GaeaPluginDefinition(
    id: "com.xocialize.gaea.samaudio", version: "0.1.0", minGaea: "1.6.0", team: "CFZS6RXUCP",
    repo: "https://github.com/xocialize-code/gaea-plugin-sam-audio", title: "SAM-Audio",
    summary: "SAM-Audio base (Meta): separates the sound you describe from a mixture, with the rest as a second stem. SAM License.",
    license: "LicenseRef-SAM", executable: "gaea-sam-audio-worker",
    models: [model()], offers: offers())
